33	/** The fixes in a folder (a project or a branch's worktree), newest first. */
34	export function listFixes(folderPath) {
35	  const root = join(folderPath, PRELUDE_DIR, FIXES_DIR);
36	  let entries;
37	  try { entries = readdirSync(root, { withFileTypes: true }); } catch { return []; }
