95	export function ago(iso, now = Date.now()) {
96	  const minutes = Math.floor(Math.max(0, now - Date.parse(iso)) / 60000);
97	  const count = (n, unit) => `${n} ${unit}${n === 1 ? '' : 's'} ago`;
98	  if (!Number.isFinite(minutes)) return 'a while ago';
99	  if (minutes < 1) return 'just now';
100	  if (minutes < 60) return count(minutes, 'minute');
101	  const hours = Math.floor(minutes / 60);
102	  if (hours < 24) return count(hours, 'hour');
103	  const days = Math.floor(hours / 24);
104	  if (days === 1) return 'yesterday';
105	  if (days < 30) return count(days, 'day');
106	  if (days < 365) return count(Math.floor(days / 30), 'month');
107	  return count(Math.floor(days / 365), 'year');
108	}
